@Composable private fun MaterialCard(m:LibraryMaterial,filho:Boolean,busy:Boolean,open:()->Unit,delete:()->Unit)=Surface(Modifier.fillMaxWidth().clickable(onClick=open),shape=RoundedCornerShape(19.dp),color=Color.White,border=BorderStroke(1.dp,AxeCloudThemeTokens.Outline)){Row(Modifier.padding(14.dp),verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(52.dp).background(Color(0xFFD7B75B).copy(.14f),RoundedCornerShape(15.dp)),contentAlignment=Alignment.Center){Icon(Icons.Outlined.PictureAsPdf,null,tint=Color(0xFF6C542E))};Column(Modifier.weight(1f).padding(horizontal=11.dp)){Text(m.category.uppercase(),color=Color(0xFF8A6D36),fontSize=9.sp,fontWeight=FontWeight.Black,letterSpacing=.7.sp);Text(m.title,color=AxeCloudThemeTokens.Ink,fontWeight=FontWeight.ExtraBold,maxLines=2,overflow=TextOverflow.Ellipsis);Text("Toque para abrir o PDF",color=AxeCloudThemeTokens.Muted,fontSize=10.sp)};if(!filho)IconButton(delete){if(busy)CircularProgressIndicator(Modifier.size(18.dp),strokeWidth=2.dp)else Icon(Icons.Outlined.DeleteOutline,"Excluir")};Icon(Icons.Outlined.OpenInNew,null,tint=Color(0xFF6C542E))}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun StudySheet(material:LibraryMaterial,s:LibraryUiState,dismiss:()->Unit,openPdf:()->Unit,send:(String,String?)->Unit,delete:(String)->Unit){var text by rememberSaveable(material.id){mutableStateOf("")};var replyTo by rememberSaveable(material.id){mutableStateOf<String?>(null)};ModalBottomSheet(onDismissRequest=dismiss,containerColor=AxeCloudThemeTokens.Canvas){Column(Modifier.navigationBarsPadding().heightIn(max=680.dp).padding(horizontal=18.dp).padding(bottom=22.dp)){Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(44.dp).background(Color(0xFFD7B75B).copy(.18f),RoundedCornerShape(14.dp)),contentAlignment=Alignment.Center){Icon(Icons.Outlined.MenuBook,null,tint=Color(0xFF6C542E))};Column(Modifier.weight(1f).padding(horizontal=10.dp)){Text(material.category.uppercase(),color=Color(0xFF8A6D36),fontSize=8.sp,fontWeight=FontWeight.Black);Text(material.title,color=AxeCloudThemeTokens.Ink,fontSize=20.sp,fontWeight=FontWeight.Black)};Button(openPdf,colors=ButtonDefaults.buttonColors(containerColor=Color(0xFF302A21))){Icon(Icons.Outlined.PictureAsPdf,null);Spacer(Modifier.width(5.dp));Text("Abrir PDF")}};HorizontalDivider(Modifier.padding(vertical=13.dp));Text("DÚVIDAS E ESCLARECIMENTOS",color=Color(0xFF8A6D36),fontSize=9.sp,fontWeight=FontWeight.Black,letterSpacing=.8.sp);if(s.loadingComments)Box(Modifier.fillMaxWidth().padding(30.dp),contentAlignment=Alignment.Center){CircularProgressIndicator()}else LazyColumn(Modifier.weight(1f),verticalArrangement=Arrangement.spacedBy(8.dp),contentPadding=PaddingValues(vertical=10.dp)){if(s.comments.isEmpty())item{Text("Nenhuma dúvida registrada. Comece a conversa sobre este estudo.",color=AxeCloudThemeTokens.Muted,fontSize=11.sp)}else items(s.comments,key={it.id}){c->CommentCard(c,c.parentId.isNotBlank(),s.manager||c.userId==s.currentUserId,{replyTo=c.id},{delete(c.id)})}};replyTo?.let{id->Text("Respondendo a ${s.comments.find{it.id==id}?.author?:"comentário"} · toque para cancelar",Modifier.clickable{replyTo=null}.padding(bottom=5.dp),color=Color(0xFF8A6D36),fontSize=9.sp)};Row(verticalAlignment=Alignment.Bottom){OutlinedTextField(text,{text=it},Modifier.weight(1f),placeholder={Text(if(replyTo==null)"Escreva sua dúvida" else "Escreva sua resposta")},minLines=1,maxLines=3,shape=RoundedCornerShape(16.dp));IconButton({val value=text.trim();if(value.isNotBlank()){send(value,replyTo);text="";replyTo=null}},enabled=!s.sendingComment&&text.isNotBlank()){if(s.sendingComment)CircularProgressIndicator(Modifier.size(19.dp),strokeWidth=2.dp)else Icon(Icons.Outlined.Send,"Enviar",tint=Color(0xFF6C542E))}};s.error?.let{Text(it,color=MaterialTheme.colorScheme.error,fontSize=10.sp)}}}}
@Composable private fun CommentCard(c:LibraryComment,reply:Boolean,canDelete:Boolean,answer:()->Unit,delete:()->Unit)=Surface(Modifier.fillMaxWidth().padding(start=if(reply)24.dp else 0.dp),shape=RoundedCornerShape(16.dp),color=Color.White,border=BorderStroke(1.dp,AxeCloudThemeTokens.Outline)){Column(Modifier.padding(11.dp)){Row(verticalAlignment=Alignment.CenterVertically){Box(Modifier.size(30.dp).background(Color(0xFFD7B75B).copy(.16f),CircleShape),contentAlignment=Alignment.Center){Icon(if(c.leadership)Icons.Outlined.VerifiedUser else Icons.Outlined.Person,null,Modifier.size(16.dp),tint=Color(0xFF6C542E))};Column(Modifier.weight(1f).padding(start=8.dp)){Text(c.author,color=AxeCloudThemeTokens.Ink,fontSize=11.sp,fontWeight=FontWeight.Black);Text(if(c.leadership)"LIDERANÇA" else "MEMBRO DA CASA",color=Color(0xFF8A6D36),fontSize=7.sp,fontWeight=FontWeight.Black)}};Text(c.text,color=AxeCloudThemeTokens.Ink,fontSize=12.sp,lineHeight=17.sp,modifier=Modifier.padding(top=8.dp));Row{if(!reply)TextButton(answer,contentPadding=PaddingValues(horizontal=5.dp)){Icon(Icons.Outlined.Reply,null,Modifier.size(14.dp));Text("Responder",fontSize=9.sp)};if(canDelete)TextButton(delete,contentPadding=PaddingValues(horizontal=5.dp)){Icon(Icons.Outlined.DeleteOutline,null,Modifier.size(14.dp),tint=MaterialTheme.colorScheme.error);Text("Excluir",fontSize=9.sp,color=MaterialTheme.colorScheme.error)}}}}
@OptIn(ExperimentalMaterial3Api::class) @Composable private fun UploadSheet(uploading:Boolean,error:String?,dismiss:()->Unit,upload:(Uri,String,String)->Unit){var title by rememberSaveable{mutableStateOf("")};var category by rememberSaveable{mutableStateOf("Cantigas")};var uri by remember{mutableStateOf<Uri?>(null)};val picker=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){uri=it};ModalBottomSheet(onDismissRequest=dismiss,containerColor=AxeCloudThemeTokens.Canvas){Column(Modifier.navigationBarsPadding().padding(horizontal=20.dp).padding(bottom=24.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){Text("Publicar estudo",color=AxeCloudThemeTokens.Ink,fontSize=24.sp,fontWeight=FontWeight.Black);OutlinedTextField(title,{title=it},Modifier.fillMaxWidth(),label={Text("Título")},shape=RoundedCornerShape(15.dp));Row(Modifier.horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(7.dp)){listOf("Cantigas","História","Ervas","Orixás","Fundamentos").forEach{c->FilterChip(category==c,{category=c},label={Text(c)})}};OutlinedButton({picker.launch(arrayOf("application/pdf"))},Modifier.fillMaxWidth().height(52.dp)){Icon(Icons.Outlined.AttachFile,null);Spacer(Modifier.width(6.dp));Text(if(uri==null)"Escolher PDF" else "PDF selecionado")};error?.let{Text(it,color=MaterialTheme.colorScheme.error)};Button({uri?.let{upload(it,title,category)}},Modifier.fillMaxWidth().height(52.dp),enabled=!uploading&&uri!=null&&title.isNotBlank(),colors=ButtonDefaults.buttonColors(containerColor=Color(0xFF302A21))){if(uploading)CircularProgressIndicator(Modifier.size(19.dp),strokeWidth=2.dp,color=Color.White)else Text("Publicar na biblioteca")}}}}
